'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=x=>esc(JSON.stringify(x,null,2));
const S={project:null,projects:[],directory:[],csrf:'',page:0,kind:'source',person:null,question:null,route:'dashboard',filters:{}};
const main=$('#main'),modal=$('#modal');
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json','X-CSRF-Token':S.csrf}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d;}
const params=o=>new URLSearchParams(Object.entries(o).filter(([,v])=>v!==undefined&&v!==null&&v!=='')).toString();
const records=(kind,extra={})=>api('records?'+params({project:S.project,kind,limit:60,offset:S.page*60,...extra}));
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(S.toast);S.toast=setTimeout(()=>$('#toast').style.display='none',5500);}
function external(url,label='Open provider search ↗'){return /^https?:\/\//i.test(url||'')?`<a class="button small" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:'<span class="meta">No safe external link</span>';}
const button=(label,action,id='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const tag=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
function heading(title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">THE RESEARCH NOTEBOOK</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="actions">${actions}</div></div>`;}
function empty(title,desc,action=''){return `<div class="empty"><h2>${esc(title)}</h2><p>${esc(desc)}</p>${action}</div>`;}
function demo(){return S.projects.find(p=>p.id===S.project)?.demo?'<div class="demo-banner">FICTIONAL DEMONSTRATION · These people and evidence are invented. Your imported research stays in its own project.</div>':'';}
function showDialog(title,html){$('#modal-body').innerHTML='<button type="button" class="dialog-close" data-action="close" aria-label="Close dialog">×</button>'+`<h2 id="dialog-title">${esc(title)}</h2>`+html;if(!modal.open)modal.showModal();}
function fail(e){toast(e.message||String(e));}
function selectOptions(list,value='',blank='Choose…'){return (blank?`<option value="">${esc(blank)}</option>`:'')+list.map(x=>{let [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}"${v===value?' selected':''}>${esc(l)}</option>`}).join('');}
function field(name,label,value='',type='text',options=null,full=false,help=''){let control;if(options)control=`<select name="${name}" id="f-${name}">${selectOptions(options,value,'')}</select>`;else if(type==='textarea'||type==='json')control=`<textarea name="${name}" id="f-${name}"${type==='json'?' spellcheck="false"':''}>${esc(type==='json'?JSON.stringify(value,null,2):value)}</textarea>`;else control=`<input name="${name}" id="f-${name}" type="${type}" value="${esc(value)}">`;return `<div class="field ${full?'full':''}"><label for="f-${name}">${esc(label)}</label>${control}${help?`<div class="form-help">${esc(help)}</div>`:''}</div>`;}
function form(html,handler,label='Save'){showDialog(S.formTitle||'Edit',`<form id="editor"><div class="form-grid">${html}</div><div class="form-error" hidden></div><div class="form-footer">${button('Cancel','close')}<button class="primary" type="submit">${esc(label)}</button></div></form>`);$('#editor').onsubmit=async ev=>{ev.preventDefault();const f=ev.currentTarget,b=$('button[type=submit]',f);b.disabled=true;try{await handler(Object.fromEntries(new FormData(f)),f);modal.close();await refresh();}catch(e){const err=$('.form-error',f);err.hidden=false;err.textContent=e.message;b.disabled=false;}};}
async function bootstrap(){const b=await api('bootstrap');Object.assign(S,{csrf:b.csrf,projects:b.projects,directory:b.directory,preferences:b.preferences,storage:b.storage});if(!S.projects.some(p=>p.id===S.project))S.project=S.projects[0]?.id||null;$('#project').innerHTML=S.projects.map(p=>`<option value="${p.id}"${p.id===S.project?' selected':''}>${esc(p.name)}</option>`).join('');}
async function refresh(){await bootstrap();await route();}
async function route(){const [r,id]=location.hash.slice(1).split('/');S.route=r||'dashboard';if(S.route==='person')S.person=id;$$('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===(S.route==='person'?'people':S.route)));$('#breadcrumb').textContent=(S.projects.find(p=>p.id===S.project)?.name||'YOUR WORKSPACE').toUpperCase();main.innerHTML='<div class="progress"><span class="spinner"></span>Opening your notebook…</div>';try{const fn={dashboard,people,person,explorer,next,log,evidence,import:imports,settings,pathways,search:smartSearch}[S.route]||dashboard;await fn();}catch(e){main.innerHTML=empty('Something needs attention',e.message,button('Try again','refresh'));}}
async function dashboard(){const [counts,questions,persons,tasks]=await Promise.all([api('counts?project='+S.project),records('question',{offset:0,limit:4}),records('person',{offset:0,limit:5}),records('task',{offset:0,limit:4})]);main.innerHTML=demo()+heading('A little closer to their story.','Pick up a question, follow a source, and leave a clear trail for your next visit.')+`<section class="hero"><div><div class="eyebrow">FOLLOW THE EVIDENCE</div><h2>Every family story begins<br>with a better question.</h2><p>Your people, sources, and open questions in one private place. Start with what you know; keep room for what you don’t.</p><div class="actions"><a href="#search" class="button primary">Search historical sources ↗</a><a href="#explorer" class="button">Explore resources</a></div></div><div class="hero-art" aria-hidden="true"><div class="paper-art"></div></div></section><div class="stats">${[['People in this project',counts.person||0],['Open questions',questions.total],['Sources collected',counts.source||0],['Searches recorded',counts.log||0]].map(([label,n])=>`<div class="stat"><strong>${n}</strong><span>${label}</span></div>`).join('')}</div><div class="grid"><section class="panel"><div class="panel-head"><h2>Questions on your desk</h2>${button('＋ Add question','new-question','','small')}</div>${questions.items.map(q=>`<article class="question"><div class="tags">${tag(q.data.status||'open','green')}${tag('Research question')}</div><h3>${esc(q.data.title)}</h3><p class="meta">${esc(q.data.hypothesis||'Add a working hypothesis to guide your research.')}</p><div class="actions">${button('Work on this question →','question',q.id,'small')}${button('Edit','edit',q.id,'small')}</div></article>`).join('')||empty('Make room for a question','You can begin without a complete family tree.')}</section><div><section class="panel"><div class="panel-head"><h2>People in your notebook</h2><a href="#people">View all →</a></div>${persons.items.map(personRow).join('')}</section><section class="panel"><div class="panel-head"><h2>Next on your list</h2>${button('＋','new-task','','small')}</div>${tasks.items.map(t=>`<div class="question"><div class="line"><span>${esc(t.data.title)}</span>${button('Edit','edit',t.id,'small')}</div><span class="meta">${esc(t.data.status||'open')}</span></div>`).join('')||'<p class="meta">Add a small, concrete research task.</p>'}</section></div></div>`;}
function personRow(p){return `<div class="person-row"><div class="avatar">${esc((p.data.name||'?').split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div><strong><a href="#person/${p.id}">${esc(p.data.name)}</a></strong><p>${esc(p.data.aliases?.join(' · ')||'Dates and relationships remain evidence-led')}</p></div><a href="#person/${p.id}" aria-label="Open ${esc(p.data.name)}">→</a></div>`;}
async function people(){const data=await records('person',{q:S.peopleQuery||''});main.innerHTML=demo()+heading('People & questions','Keep identities, alternatives, and unresolved details together.',button('＋ Add person','new-person','','primary'))+`<div class="filters"><div class="wide"><label for="people-search">Search this project</label><input id="people-search" type="search" placeholder="Name, alternate spelling, or note" value="${esc(S.peopleQuery||'')}"></div>${button('Search','search-people')}</div><section class="panel"><div class="panel-head"><h2>${data.total.toLocaleString()} people</h2><span class="meta">60 per page</span></div>${data.items.map(personRow).join('')||empty('Your research starts here','Add one person or import your existing tree.',button('Import GEDCOM','import'))}</section>${pagination(data.total)}`;}
function pagination(total){return `<div class="actions">${S.page?button('← Previous','prev'):''}<span class="meta">Page ${S.page+1} · ${total} records</span>${(S.page+1)*60<total?button('Next →','page-next'):''}</div>`;}
async function person(){const p=await api('record?id='+S.person);const related=await records('',{person:p.id,limit:1000,offset:0});const a=related.items.filter(r=>r.kind==='assertion'),questions=related.items.filter(r=>r.kind==='question'),rels=related.items.filter(r=>r.kind==='relationship');S.currentPerson=p;main.innerHTML=demo()+heading(p.data.name,p.data.aliases?.join(' · ')||'A person is more than a preferred date. Keep every assertion and its evidence.',button('Edit person','edit',p.id)+button('Compare candidates','compare',p.id)+button('Smart search ↗','smart-person',p.id,'primary')+button('Source suggestions','recommend',p.id))+`<div class="tags">${tag('Living status: '+(p.data.living||'unknown'),'amber')}${tag(p.data.review||'unreviewed')}${p.data.origin?tag('Imported snapshot'):''}</div>${p.data.import_conflicts?.length?'<div class="notice warn">A repeat import conflicts with local edits. Your local values were preserved. Review the details below.</div>':''}<div class="grid"><section><div class="panel-head"><h2>Events & assertions</h2>${button('＋ Add assertion','new-assertion',p.id,'small')}</div>${a.map(assertionCard).join('')||empty('Keep what you know','Approximate dates and conflicting claims are welcome.')}<div class="panel"><h2>Relationships & research connections</h2>${rels.map(r=>`<div class="record"><strong>${esc(r.data.type)}</strong><p class="meta">Original role: ${esc(r.data.role_original||'unspecified')}</p><p class="meta">From ${esc(r.data.from_key||r.data.from_id)} → ${esc(r.data.to_key||r.data.to_id)}</p>${button('Inspect / assess','edit',r.id,'small')}</div>`).join('')}<div class="actions">${button('＋ Add connection','new-relationship',p.id,'small')}</div></div></section><div><section class="panel"><div class="panel-head"><h2>Research questions</h2>${button('＋','new-question',p.id,'small')}</div>${questions.map(q=>`<div class="question"><h3>${esc(q.data.title)}</h3><p class="meta">${esc(q.data.hypothesis)}</p>${tag(q.data.status||'open','green')}<div class="actions">${button('Investigate →','question',q.id,'small')}${button('Edit','edit',q.id,'small')}</div></div>`).join('')||'<p class="meta">What would you like to learn about this person?</p>'}</section><section class="panel"><h2>Notes & provenance</h2><p class="wrap">${esc(Array.isArray(p.data.notes)?p.data.notes.join('\n'):p.data.notes||'No notes yet.')}</p><div class="actions">${button('Raw provenance','provenance',p.id,'small')}${button('Edit history','history',p.id,'small')}</div><details><summary>All preserved person fields</summary><pre>${pretty(p.data)}</pre></details></section><section class="panel"><h2>Keep the evidence distinct</h2><p class="meta">An imported claim is not independently verified. Acceptance records your assessment, not a proof certification.</p><a href="#evidence">Open evidence workspace →</a></section></div></div>`;}
function assertionCard(a){const d=a.data;return `<article class="record"><div class="line"><h3>${esc(d.type)} ${esc(d.value||'')}</h3>${tag(d.review||'unreviewed',d.review==='disputed'?'red':'')}</div><p><strong>${esc(d.date?.original||'Date unknown')}</strong><br><span class="meta">${esc(d.place||'Place unresolved')}</span></p><p class="meta">${esc(d.date?.precision||'unknown precision')} · ${esc(d.date?.calendar||'Calendar unknown')}${d.date?.assumptions?.length?' · '+esc(d.date.assumptions.join(' ')):''}</p><div class="tags">${tag((d.citation_ids?.length||0)+' supporting citations')}${tag((d.contradicting_ids?.length||0)+' contradicting citations',d.contradicting_ids?.length?'amber':'')}</div><div class="actions">${button('Inspect / assess','edit',a.id,'small')}${button('Evidence','record',a.id,'small')}${button('Raw fields','provenance',a.id,'small')}</div>${d.import_conflicts?`<details><summary>Import conflicts — local values retained</summary><pre>${pretty(d.import_conflicts)}</pre></details>`:''}</article>`;}
function resourceCard(e,rec=null){const access=e.access?.search||['unknown'];return `<article class="resource"><div class="provider">${esc(e.provider||e.repository_type||e.kind)} · ${esc(e.kind)}</div><h3>${esc(e.name)}</h3><div class="tags">${access.map(x=>tag(x)).join('')}${tag(e.verification||'Needs verification',e.verification==='coverage checked'?'green':'amber')}</div><p class="muted">${esc(e.description)}</p><dl class="details"><dt>Coverage</dt><dd>${esc(e.geography?.join('; ')||'Unknown geography')}</dd><dt>Dates</dt><dd>${esc(e.dates?.map(x=>x.map(y=>y??'?').join('–')).join(', ')||'Unknown')}</dd><dt>Search method</dt><dd>${esc(e.capabilities?.join(' · ')||'Unknown')}</dd></dl>${rec?`<div class="notice"><strong>${esc(rec.band)} match</strong><p>${esc(rec.why.join(' '))}</p><p class="meta">Hypothesis: ${esc(rec.hypothesis.date.original||'date unknown')} · ${esc(rec.hypothesis.place||'place unknown')}</p></div><p class="meta">${esc(rec.uncertainty.join(' '))}</p><details><summary>Suggested query & alternative steps</summary><pre>${esc(rec.query)}</pre><p class="meta">Variants: ${esc(rec.variants.join(' · ')||'Add recorded name variants to the person.')}</p>${rec.alternatives.map(x=>`<p class="meta">${esc(x)}</p>`).join('')}</details>`:''}<div class="actions">${external(e.url)}${button('Details','resource',e.id,'small')}${rec?button('Copy query','copy-query',e.id,'small')+button('Log search','log-resource',e.id,'small'):button('Save','bookmark',e.id,'small')}</div></article>`;}
async function explorer(){let filters=S.filters;const result=await api('directory?'+params(filters));main.innerHTML=heading('A source worth following.','Search this curated directory. Opening a provider is a separate action; this does not query external records.',button('＋ Add resource','new-resource'))+`<div class="notice">Starter focus: Massachusetts, New Hampshire & Vermont, plus U.S. and overseas discovery. Coverage is incomplete. Unknown fields stay unknown.</div><form id="filters" class="filters"><div class="wide"><label for="q">Search directory</label><input id="q" name="q" placeholder="Place, collection, or repository" value="${esc(filters.q||'')}"></div><div><label for="kind">Entry type</label><select id="kind" name="kind">${selectOptions(['collection','repository','provider','guidance'],filters.kind,'All types')}</select></div><div><label for="place">Recorded place</label><input id="place" name="place" value="${esc(filters.place||'')}" placeholder="Massachusetts, United States"></div><div><label for="start">From year</label><input id="start" name="start" type="number" value="${esc(filters.start||'')}"></div><div><label for="end">To year</label><input id="end" name="end" type="number" value="${esc(filters.end||'')}"></div><div><label for="type">Record type</label><input id="type" name="type" value="${esc(filters.type||'')}" placeholder="probate, census…"></div><div><label for="language">Language</label><input id="language" name="language" value="${esc(filters.language||'')}" placeholder="English"></div><label class="check"><input type="checkbox" name="free" value="1" ${filters.free?'checked':''}>Free search</label><label class="check"><input type="checkbox" name="remote" value="1" ${filters.remote?'checked':''}>Remote access</label><label class="check"><input type="checkbox" name="archived" value="1" ${filters.archived?'checked':''}>Include archived</label><button class="primary">Apply filters</button></form><div class="panel-head"><h2>${result.length} resources</h2><a href="/api/csv?kind=directory">Export directory CSV ↓</a></div><div class="resource-grid">${result.map(e=>resourceCard(e)).join('')}</div>`;$('#filters').onsubmit=e=>{e.preventDefault();S.filters=Object.fromEntries(new FormData(e.currentTarget));explorer().catch(fail);};}
async function next(){const people=await records('person',{offset:0,limit:1000});if(S.person&&!people.items.some(x=>x.id===S.person)){const selected=await api('record?id='+S.person);if(selected.project===S.project)people.items.push(selected);else S.person=null;}if(!S.person)S.person=people.items[0]?.id;const questions=await records('question',{offset:0,limit:1000,person:S.person});if(S.question&&!questions.items.some(x=>x.id===S.question))S.question=null;const rec=S.person?await api('recommend?'+params({person:S.person,question:S.question})):null;S.recommendations=rec?.items||[];main.innerHTML=heading('Where to look next.','Explainable suggestions from your local research. No AI or external account required.')+`<div class="filters"><div><label for="next-person">Person / hypothesis</label><select id="next-person">${selectOptions(people.items.map(p=>[p.id,p.data.name]),S.person,'')}</select></div><div><label for="next-question">Research question</label><select id="next-question">${selectOptions(questions.items.map(q=>[q.id,q.data.title]),S.question,'General research')}</select></div>${button('Update suggestions','update-next','','primary')}${button('Search these people online','smart-person',S.person,'primary')+button('Optional AI workspace','ai-workspace')}</div>${rec?`<div class="notice">${esc(rec.notice)} Ranking rules v${rec.rule_version}. Dates and places below identify the assertion used.</div><div class="resource-grid">${rec.items.slice(0,30).map(r=>resourceCard(r.resource,r)).join('')}</div><details><summary>${rec.exclusions.length} exclusions explained</summary>${rec.exclusions.map(x=>`<p class="meta"><strong>${esc(x.name)}</strong>: ${esc(x.reason)}</p>`).join('')}</details>`:empty('Add a person to begin','Even an approximate date or recorded place helps.',button('＋ Add person','new-person'))}`;}
async function log(){const data=await records('log');main.innerHTML=heading('Leave a trail for next time.','Useful findings, no-result searches, and unavailable records are different outcomes.',button('＋ Log a search','new-log','','primary'))+`<div class="panel-head"><h2>${data.total} logged searches</h2><a href="/api/csv?kind=log&project=${S.project}">Export research log CSV ↓</a></div>${data.items.map(r=>`<article class="record"><div class="line"><h3>${esc(r.data.query)}</h3>${tag(r.data.outcome,r.data.outcome==='no result'?'amber':'green')}</div><p class="meta">${esc(S.directory.find(e=>e.id===r.data.collection_id)?.name||'Collection unspecified')} · ${esc(r.data.search_date||'Date not recorded')}</p><p>${esc(r.data.notes||'')}</p><p class="meta">Coverage: ${esc(r.data.coverage||'not recorded')} · Access limitations: ${esc(r.data.limitations||'not recorded')}</p>${button('Inspect / edit','edit',r.id,'small')}</article>`).join('')||empty('Not searched yet','Log the exact query and coverage so you can make a different next move.')} ${pagination(data.total)}`;}
async function evidence(){const data=await records(S.kind);main.innerHTML=heading('Evidence, with its context.','Sources describe material. Citations locate it. Assertions record claims; conclusions explain your reasoning.',button('＋ Add '+S.kind.replace('_',' '),'new-'+S.kind,'','primary'))+`<div class="tabs">${['source','citation','assertion','relationship','lead','conclusion','ai_artifact','bookmark','place','task'].map(k=>button(k.replace('_',' '),'evidence-kind',k,k===S.kind?'active':'')).join('')}</div><div class="notice">Thorough searching, citations, analysis, conflict resolution, and written conclusions support careful genealogy. This workspace does not certify the Genealogical Proof Standard.</div>${data.items.map(r=>r.kind==='assertion'?assertionCard(r):`<article class="record"><div class="line"><h3>${esc(r.data.title||r.data.name||r.data.locator||r.data.type||r.data.task||r.kind)}</h3>${tag(r.data.review||'unreviewed')}</div><p class="meta">${esc(r.data.excerpt||r.data.notes?.toString()||r.data.rationale||r.data.query||'')}</p><div class="actions">${button('Inspect','record',r.id,'small')}${button('Edit / assess','edit',r.id,'small')}${button('History','history',r.id,'small')}</div></article>`).join('')||empty('Keep the source and the claim','Add evidence without forcing a single interpretation.')}${pagination(data.total)}`;}
async function pathways(){main.innerHTML=heading('Different histories. Different paths.','Choose a pathway deliberately. Identity and ancestry are never inferred from a person’s name.')+`<div class="resource-grid">${S.directory.filter(e=>e.id.startsWith('path-')).map(e=>resourceCard(e)).join('')}</div><div class="notice warn">Access and privacy vary by jurisdiction. Some guidance still needs verification; confirm it with the responsible archive or authority.</div>`;}
async function imports(){const imports=await api('imports?project='+S.project);main.innerHTML=heading('Bring your research with you.','A local snapshot of your tree, with original files and provenance. This is not ongoing Ancestry synchronization.')+`<div class="two"><section class="panel"><div class="eyebrow">01 · IMPORT</div><h2>Start from an existing tree</h2><p class="meta">GEDCOM 5.5 / 5.5.1 or 7.0.x, a ZIP containing one GEDCOM, or unencrypted GEDZIP. Optional local media files or ZIP.</p><label for="ged-file">GEDCOM or archive</label><input id="ged-file" type="file" accept=".ged,.gdz,.zip"><br><br><label for="media-file">Accompanying media ZIP / files (optional)</label><input id="media-file" type="file" multiple><label for="media-folder">Or a media folder (optional)</label><input id="media-folder" type="file" webkitdirectory multiple><p class="form-help">Select the folder containing the paths written in the GEDCOM; its top folder is stripped. For FILE media/photo.jpg, select the parent of media, or supply a ZIP with media/photo.jpg.</p><br><label for="import-lineage">Import destination</label><select id="import-lineage">${selectOptions(S.projects.map(p=>[p.id,p.name]),'','New separate project (recommended for first import)')}</select><p class="form-help">For an updated export, select its original lineage. Reused identifiers always require identity review.</p><div class="actions">${button('Preview import →','preview-import','','primary')}</div><div id="import-status"></div></section><section class="panel"><div class="eyebrow">02 · PORTABILITY</div><h2>A complete research backup</h2><p class="meta">Includes your projects, original imports, evidence links, managed attachments, directory edits, and AI artifacts. API credentials are excluded.</p><div class="actions"><a class="button primary" href="/api/backup">Download backup ZIP ↓</a><a class="button" href="/api/export">Structured JSON ↓</a></div><hr class="divider"><h3>Restore into a separate destination</h3><label for="restore-file">blueGene ZIP or structured JSON</label><input type="file" id="restore-file" accept=".zip,.json"><div class="actions">${button('Validate & preview restore','preview-restore')}</div><p class="form-help">Checksums and record links are checked before a new local database is created.</p></section></div><section class="panel"><h2>Import history · current project</h2>${imports.map(i=>`<div class="record"><div class="line"><strong>${esc(i.filename)}</strong><span class="meta">${esc(i.created.slice(0,10))}</span></div><div class="actions">${button('View import report','import-report',i.id,'small')}<a class="button small" href="/api/original?id=${i.id}">Original file ↓</a>${button('Undo import','undo-import',i.id,'small danger')}</div></div>`).join('')||'<p class="meta">No imported snapshots in this project.</p>'}</section><section class="panel"><h2>Before you call a migration complete</h2><p class="meta">Inspect the report and representative profiles. Check original fields against imported assertions and citations. Photos or documents absent from your export cannot be recovered by this app.</p><p class="meta">ANSEL currently requires a UTF-8 re-export. Absolute media paths are not read; supply a relative-path export and a selected media folder. Unsupported tags remain in raw provenance.</p>${external('https://help.ancestry.co.uk/hc/en-gb/articles/53933352542867-Uploading-and-Downloading-Trees','Official Ancestry export guidance ↗')}</section>`;}
async function settings(){const status=await api('ai/status');S.aiStatus=status;const p=status.preferences;main.innerHTML=heading('Your notebook, your choices.','AI is optional. Your directory, evidence, and deterministic recommendations work without it.')+`<div class="two"><section class="panel"><h2>AI preferences</h2><form id="preferences"><label class="check"><input type="checkbox" name="enabled" ${p.ai_enabled?'checked':''}>Enable user-triggered external AI actions</label><label class="check"><input type="checkbox" name="sensitive" ${p.allow_sensitive?'checked':''}>Allow living / unknown-status people and sensitive attachments in reviewed previews</label>${field('provider','Default provider',p.provider||'openai','text',['openai','anthropic'])}${field('model','Exact default model ID',p.model||'')}${field('overrides','Task overrides (JSON)',p.overrides||{},'json',null,true,'Example: {"transcription":{"provider":"anthropic","model":"your-exact-model-id"}}')}${field('access','Access preferences (JSON)',p.access||{},'json',null,true,'Example: {"subscriptions":["ancestry"],"free":false,"remote":true}') }<div class="actions"><button class="primary">Save preferences</button>${button('Open reviewed AI workspace','ai-workspace')}</div></form><p class="form-help">No inference call occurs when opening Settings. Each run requires a fresh data preview and consent. No cross-provider fallback is implemented.</p></section><div>${['openai','anthropic'].map(provider=>`<section class="panel"><div class="panel-head"><h2>${provider==='openai'?'OpenAI':'Anthropic'}</h2>${tag(status.providers[provider].configured?'Key configured':'No key',status.providers[provider].configured?'green':'amber')}</div><label for="key-${provider}">API key — backend only</label><input type="password" id="key-${provider}" autocomplete="off" placeholder="Paste key to save; never exported"><div class="actions">${button('Save key','save-key',provider,'small')}${button('Remove key','remove-key',provider,'small')}${button('Refresh models','models',provider,'small')}${button('Test model','test-model',provider,'small')}</div><p class="meta">${status.providers[provider].cache?'Cached model list from '+esc(status.providers[provider].cache.refreshed):'No cached model list.'}</p><details><summary>Available model IDs & metadata</summary><pre>${pretty(status.providers[provider].cache?.models||[])}</pre></details></section>`).join('')}</div></div><div class="panel"><h2>Directory maintenance</h2><p class="meta">Edit coverage, access, verification references and archive status in the explorer. Seed updates preserve local overrides and surface conflicting fields.</p><div class="actions"><a class="button" href="#explorer">Open directory</a>${button('Add directory entry','new-resource')}</div></div><section class="panel"><h2>Local storage & privacy</h2><p class="wrap"><code>${esc(S.storage)}</code></p><p class="meta">SQLite stores research, original imports, and a managed attachment BLOB store in atomic transactions. Credentials are a separate owner-readable file. Local storage is not encryption; use your operating system’s disk encryption and protect exported backups.</p><a href="#import">Back up or restore →</a></section>`;$('#preferences').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('preferences',{preferences:{ai_enabled:f.has('enabled'),allow_sensitive:f.has('sensitive'),provider:f.get('provider'),model:f.get('model'),overrides:JSON.parse(f.get('overrides')),access:JSON.parse(f.get('access'))}});toast('Preferences saved');}catch(e){fail(e);}};}
const reviewOptions=['unreviewed','tentative','accepted by user','disputed','rejected'];
async function editRecord(kind,id=null,personId=null,initial={}){if(kind==='ai_artifact'&&!id){return aiWorkspace();}let r=id?await api('record?id='+id):{kind,person:personId||null,data:initial};kind=r.kind;const d=r.data;const [people,sources,citations,questions,assertions]=await Promise.all(['person','source','citation','question','assertion'].map(k=>records(k,{offset:0,limit:1000})));for(const [list,ids] of [[people,[r.person,personId,d.from_id,d.to_id]],[sources,[d.source_id]],[questions,[d.question_id]],[assertions,[d.assertion_id]],[citations,[...(d.citation_ids||[]),...(d.contradicting_ids||[])]]]){for(const rid of ids.filter(Boolean)){if(!list.items.some(x=>x.id===rid))list.items.push(await api('record?id='+rid));}}const citationPicker=(name,label,selected=[])=>`<fieldset class="field full"><legend>${esc(label)}</legend><div class="scroll">${citations.items.map(c=>`<label class="check"><input type="checkbox" name="${name}" value="${c.id}" ${selected.includes(c.id)?'checked':''}>${esc(sources.items.find(s=>s.id===c.data.source_id)?.data.title||'Source')} · ${esc(c.data.locator||'No locator')} · ${esc((c.data.excerpt||'').slice(0,100))}</label>`).join('')||'<p class="meta">Add a source and citation in Evidence & citations first.</p>'}</div></fieldset>`;const choices=items=>[['','None'],...items.map(x=>[x.id,x.data.name||x.data.title||x.data.locator||x.data.type||x.id])];let html='';
if(kind==='person')html=(!id?field('initial_date','Initial birth date (optional)','','text',null,false,'Approximate dates such as ABT 1840 are welcome.')+field('initial_place','Initial birth place as recorded'): '')+field('name','Name as recorded',d.name)+field('aliases','Aliases / maiden / original-script names',(d.aliases||[]).join('; '),'text',null,false,'Separate names with semicolons.')+field('living','Living status',d.living||'unknown','text',['unknown','yes','no']);
else html=field('person','Person',r.person||personId||'','text',choices(people.items));
if(kind==='assertion')html+=field('type','Event / assertion type',d.type||'BIRT')+field('value','Claim / value',d.value||'')+field('date','Original date expression',d.date?.original||'','text',null,false,'ABT 1840, BEF 1850, BET 1840 AND 1845; original wording is retained.')+field('place','Place as recorded',d.place||'')+citationPicker('citation_ids','Supporting citations',d.citation_ids)+citationPicker('contradicting_ids','Contradicting citations',d.contradicting_ids);
if(kind==='question')html+=field('title','Research question',d.title)+field('hypothesis','Working hypothesis',d.hypothesis,'textarea',null,true)+field('status','Status',d.status||'open','text',['open','in progress','resolved','paused'])+field('assertion_id','Use a specific assertion as hypothesis',d.assertion_id||'','text',choices(assertions.items))+field('planned_searches','Planned searches',d.planned_searches,'textarea',null,true)+field('conclusion','Written conclusion',d.conclusion,'textarea',null,true)+citationPicker('citation_ids','Conclusion citation',d.citation_ids)+field('unresolved_conflicts','Unresolved conflicts',d.unresolved_conflicts,'textarea',null,true);
if(kind==='source')html+=field('title','Source title',d.title)+field('creator','Creator / author',d.creator)+field('repository','Repository',d.repository)+field('collection','Collection',d.collection)+field('source_date','Source date',d.source_date)+field('url','Source URL',d.url,'url')+field('access_date','Access date',d.access_date||new Date().toISOString().slice(0,10),'date')+field('format','Evidence form',d.format||'unknown','text',['unknown','original image','transcription','index','published analysis','contributed tree','photograph','finding aid'])+field('informant','Informant knowledge / assessment',d.informant||'unknown')+field('excerpt','Transcription or excerpt',d.excerpt,'textarea',null,true);
if(kind==='citation')html+=field('source_id','Source',d.source_id||'','text',choices(sources.items))+field('locator','Page / image / entry locator',d.locator)+field('excerpt','Exact excerpt for review',d.excerpt,'textarea',null,true)+field('url','Specific source URL',d.url,'url')+field('access_date','Access date',d.access_date||new Date().toISOString().slice(0,10),'date');
if(kind==='relationship')html+=field('from_id','From person',d.from_id||personId||'','text',choices(people.items))+field('to_id','To person',d.to_id||'','text',choices(people.items))+field('type','Relationship / connection',d.type||'unspecified','text',['unspecified','biological','adoptive','foster','step','partner','associate','witness','neighbor','household'])+field('role_original','Original role label',d.role_original)+citationPicker('citation_ids','Citations',d.citation_ids);
if(kind==='log')html+=field('question_id','Research question',d.question_id||S.question||'','text',choices(questions.items))+field('collection_id','Collection / resource',d.collection_id||'','text',[['','Unspecified'],...S.directory.map(e=>[e.id,e.name])])+field('query','Exact query',d.query,'textarea',null,true)+field('variants','Spelling variants searched',d.variants)+field('filters','Filters applied',d.filters)+field('search_date','Search date',d.search_date||new Date().toISOString().slice(0,10),'date')+field('coverage','Years / coverage actually searched',d.coverage)+field('limitations','Coverage / access limitations',d.limitations)+field('outcome','Outcome',d.outcome||'no result','text',['useful finding','possible match','no result','inaccessible','follow-up needed'])+field('url','Saved result / provider link',d.url,'url')+citationPicker('citation_ids','Citations',d.citation_ids);
if(['task','lead','conclusion','bookmark'].includes(kind))html+=field('title','Title',d.title)+field('status','Status',d.status||'open')+field('url','Related link',d.url,'url')+field('question_id','Research question',d.question_id||'','text',choices(questions.items))+citationPicker('citation_ids','Supporting citation',d.citation_ids)+field('text','Research text',d.text,'textarea',null,true);
if(kind==='place')html+=field('recorded','Place as recorded',d.recorded)+field('normalized','Reviewed normalized place',d.normalized)+field('aliases','Historical aliases',(d.aliases||[]).join('; '))+field('dates','Effective date ranges',d.dates||[],'json',null,true,'Example: [[1730,1800]]. Never infer jurisdiction from modern boundaries.')+field('references','Supporting references',d.references||[],'json',null,true);
if(kind==='ai_artifact')html+=`<div class="field full"><div class="notice">Raw model output and input context remain immutable. Changes here record your review only.</div><pre>${pretty(d.output)}</pre></div>`+field('corrected_transcript','Corrected transcription (separate from raw output)',d.corrected_transcript,'textarea',null,true);
html+=field('review','Assessment',d.review||'unreviewed','text',reviewOptions)+field('rationale','Assessment rationale',d.rationale,'textarea',null,true);
if(kind!=='ai_artifact')html+=field('notes','Notes',Array.isArray(d.notes)?d.notes.join('\n'):d.notes||'','textarea',null,true)+`<div class="field full"><label for="attachment-upload">Attach a local image, PDF or TXT</label><input id="attachment-upload" type="file" accept=".jpg,.jpeg,.png,.pdf,.txt"><p class="form-help">PDFs and other attachments download as files; active content is never embedded in this app.</p></div>`;
S.formTitle=(id?'Edit ':'Add ')+kind.replace('_',' ');form(html,async (f,formEl)=>{const data={...d};for(const [k,v] of Object.entries(f)){if(['person','initial_date','initial_place'].includes(k))continue;if(['citation_ids','contradicting_ids'].includes(k))data[k]=v.split(',').map(x=>x.trim()).filter(Boolean);else if(k==='aliases')data[k]=v.split(';').map(x=>x.trim()).filter(Boolean);else if(kind==='place'&&['dates','references'].includes(k))data[k]=JSON.parse(v);else if(k==='date'&&d.date?.original===v)data[k]=d.date;else data[k]=v;}
for(const key of ['citation_ids','contradicting_ids']){if($('input[name='+key+']',formEl)||$('[data-unused='+key+']',formEl))data[key]=new FormData(formEl).getAll(key);}
if(kind==='ai_artifact'){data.acceptance_history=[...(d.acceptance_history||[]),{at:new Date().toISOString(),review:data.review,rationale:data.rationale}];}
if(data.review==='accepted by user'&&!data.rationale?.trim())throw Error('Add a rationale for your acceptance.');
if(kind==='source'&&!id){const duplicate=sources.items.find(s=>s.data.title.trim().toLowerCase()===data.title?.trim().toLowerCase()||(data.url&&s.data.url===data.url));if(duplicate&&!formEl.dataset.duplicateReviewed){formEl.dataset.duplicateReviewed='yes';throw Error('Possible duplicate source: '+duplicate.data.title+'. Existing provenance will be kept. Save again to create a separate source intentionally.');}}
let saved=await api('save',{project:S.project,kind,id:r.id,person:kind==='person'?(r.id||null):(f.person||null),data});if(kind==='person'&&!id&&(f.initial_date||f.initial_place))await api('save',{project:S.project,kind:'assertion',person:saved.id,data:{type:'BIRT',date:f.initial_date||'',place:f.initial_place||'',place_status:'unresolved',review:'unreviewed'}});const file=$('#attachment-upload',formEl)?.files[0];if(file){const a=await fileData(file);const attachment=await api('attach',{project:S.project,...a});await api('save',{project:S.project,kind,id:saved.id,person:saved.person,data:{...saved.data,attachment_ids:[...(saved.data.attachment_ids||[]),attachment.id]}});}toast('Saved locally');});}
async function editResource(id){const e=S.directory.find(x=>x.id===id)||{name:'',kind:'collection',url:'',description:'',provider:'',geography:[],dates:[],record_types:[],capabilities:[],languages:[],access:{search:['unknown'],images:['unknown'],copies:['unknown']},verification:'Needs verification',verification_scope:[],rights:'unknown',archived:false};S.formTitle=id?'Edit directory entry':'Add directory entry';form(field('name','Name',e.name)+field('kind','Entry type',e.kind,'text',['provider','collection','repository','guidance'])+field('url','Canonical URL',e.url,'url',null,true)+field('description','Description',e.description,'textarea',null,true)+field('provider','Provider ID',e.provider)+field('geography','Geographic coverage',e.geography?.join('; '),'text',null,false,'Separate recorded jurisdictions with semicolons.')+field('dates','Date coverage ranges',e.dates||[],'json')+field('record_types','Record types',e.record_types?.join('; '))+field('capabilities','Search capabilities',e.capabilities?.join('; '))+field('access','Search / image / copy access',e.access,'json',null,true)+field('verification','Verification status',e.verification,'text',['Needs verification','link checked','coverage checked','blocked'])+field('last_checked','Last checked date',e.last_checked||'','date')+field('verification_source','Verification reference',e.verification_source||'','url',null,true)+field('verification_scope','What was actually checked',e.verification_scope?.join('; '),'text',null,true,'Link availability is different from coverage, access and integration behavior.')+field('limitations','Limitations and gaps',e.limitations,'textarea',null,true)+field('extra','Other metadata (editable JSON)',Object.fromEntries(Object.entries(e).filter(([k])=>!['id','name','kind','url','description','provider','geography','dates','record_types','capabilities','access','verification','last_checked','verification_source','verification_scope','limitations','archived'].includes(k))),'json',null,true)+field('archived','Archive entry',String(!!e.archived),'text',['false','true']),async f=>{let data={...e,...JSON.parse(f.extra),...f};delete data.extra;delete data.id;for(const k of ['geography','record_types','capabilities','verification_scope'])data[k]=f[k].split(';').map(x=>x.trim()).filter(Boolean);data.dates=JSON.parse(f.dates);data.access=JSON.parse(f.access);data.archived=f.archived==='true';if(data.verification!=='Needs verification'&&(!data.last_checked||!data.verification_source||!data.verification_scope.length))throw Error('Verification requires a date, reference and explicit scope.');await api('directory',{id,data});toast('Directory updated; seed overrides preserved');});}
async function fileData(file,name){if(file.size>64*1024*1024)throw Error('File exceeds 64 MiB limit.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:name||file.name,data:reader.result.split(',')[1]});reader.onerror=()=>reject(Error('Unable to read selected file'));reader.readAsDataURL(file);});}
async function pollJob(job,onDone){showDialog('Operation in progress',`<div class="progress"><span class="spinner"></span><span id="job-status" role="status">Starting…</span></div><p class="meta">Cancellation is best effort. Completed local commits cannot be cancelled; AI charges may already have occurred.</p>${button('Request cancellation','cancel-job',job)}`);return new Promise((resolve,reject)=>{async function tick(){try{const j=await api('job?id='+job);if($('#job-status'))$('#job-status').textContent=j.progress||j.status;if(j.status==='running'){setTimeout(tick,600);return;}if(j.status!=='complete')throw Error(j.error||'Operation cancelled');if(onDone)await onDone(j.result);resolve(j.result);}catch(e){showDialog('Operation stopped',`<div class="notice warn">${esc(e.message)}</div>${button('Close','close')}`);reject(e);}}tick();});}
async function previewImport(){const file=$('#ged-file').files[0];if(!file)throw Error('Choose a GEDCOM file or archive.');const raw=await fileData(file);const media=[];for(const f of $('#media-file').files)media.push(await fileData(f));for(const f of $('#media-folder').files){const path=f.webkitRelativePath.split('/').slice(1).join('/');media.push(await fileData(f,path));}const project=$('#import-lineage').value;const j=await api('import/preview',{filename:file.name,data:raw.data,media,project});await pollJob(j.job,async result=>{S.importStage=result;showDialog('Review your import',`<p class="meta">Nothing has been committed. Original fields remain available after import.</p>${result.identical?'<div class="notice">This exact file is already in this lineage. Committing will return the existing project without duplicates.</div>':''}<div class="stats">${['person','relationship','assertion','citation'].map(k=>[k,result.report.counts[k]||0]).map(([k,n])=>`<div class="stat"><strong>${n}</strong><span>${esc(k)}</span></div>`).join('')}</div><div class="notice warn">Check warnings, raw preservation, media matches and profiles before calling this migration complete.</div><details open><summary>Import report, warnings & representative profiles</summary><pre>${pretty(result.report)}</pre></details>${result.comparison?`<details open><summary>Proposed changes & conflicts (${result.comparison.length})</summary><pre>${pretty(result.comparison)}</pre></details><p>${esc(result.identity_notice)}</p><details><summary>Person identifier mappings — review every match</summary><pre>${pretty(result.person_mappings)}</pre></details><label class="check"><input id="identity-confirmed" type="checkbox">I reviewed the person mappings and confirm these identifiers refer to the same people.</label>`:''}<label for="import-name">New project name</label><input id="import-name" value="${esc(file.name.replace(/\.[^.]+$/,''))}"><div class="actions">${button('Discard preview','discard-import',result.stage)}${button('Commit reviewed import','commit-import',result.stage,'primary')}</div>`);});}
async function aiWorkspace(){const [status,rec,atts]=await Promise.all([api('ai/status'),records('',{offset:0,limit:1000,person:S.person||undefined}),api('attachments?project='+S.project)]);const prefs=status.preferences;if(!prefs.ai_enabled){showDialog('AI is disabled','<p>Core research works without AI. Enable external AI actions and configure credentials in Settings to use these optional workflows.</p><a class="button" href="#settings" data-action="close">Open settings</a>');return;}
let items=rec.items.filter(r=>['person','question','assertion','source','citation'].includes(r.kind));S.aiRecords=items;showDialog('Prepare a scoped AI action',`<form id="ai-form"><div class="form-grid">${field('task','Task','planning','text',[['planning','Research planning'],['query','Query variants & multilingual searches'],['transcription','Transcription & extraction'],['comparison','Evidence comparison'],['summary','Summary & report draft']])}${field('provider','Per-run provider',prefs.provider||'openai','text',['openai','anthropic'])}${field('model','Exact model ID',prefs.model||'')}${field('limit','Maximum output tokens',1500,'number')}<div id="effort-control" class="field full"></div><div class="field full"><label>Choose only the records needed (maximum 30)</label><div class="scroll"><div class="list">${items.map(r=>`<label class="check"><input type="checkbox" name="record" value="${r.id}">${esc(r.kind)} · ${esc(r.data.name||r.data.title||r.data.locator||r.data.type||r.id)}</label>`).join('')}</div></div></div><div class="field full"><label>Optional attachments (maximum 3)</label>${atts.map(a=>`<label class="check"><input type="checkbox" name="attachment" value="${a.id}">${esc(a.name)} · ${esc(a.mime)}</label>`).join('')||'<p class="meta">No local attachments in this project.</p>'}</div></div><div class="actions"><button class="primary">Prepare editable preview →</button></div><div class="form-error" hidden></div></form>`);const refreshEffort=()=>{const provider=$('#f-provider').value,model=$('#f-model').value,caps=status.providers[provider]?.cache?.models?.find(m=>m.id===model)?.capabilities?.effort;const available=provider==='anthropic'&&caps?.supported?Object.entries(caps).filter(([k,v])=>v?.supported===true).map(([k])=>k):[];$('#effort-control').innerHTML=available.length?field('effort','Effort (cached supported controls)','','text',[['','Provider default'],...available.map(x=>[x,x])]):'<p class="form-help">Effort controls appear only when the selected model’s metadata explicitly reports support.</p>';};$('#f-provider').onchange=refreshEffort;$('#f-model').oninput=refreshEffort;refreshEffort();$('#f-task').onchange=()=>{const o=prefs.overrides?.[$('#f-task').value];if(o){$('#f-provider').value=o.provider||prefs.provider;$('#f-model').value=o.model||prefs.model;}refreshEffort();};$('#ai-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget);const b={project:S.project,task:f.get('task'),provider:f.get('provider'),model:f.get('model'),limit:Number(f.get('limit')),effort:f.get('effort')||null,record_ids:f.getAll('record'),attachment_ids:f.getAll('attachment')};try{const p=await api('ai/preview',b);S.aiPreview={p,b};showAIPreview();}catch(e){$('.form-error',ev.currentTarget).hidden=false;$('.form-error',ev.currentTarget).textContent=e.message;}};}
function showAIPreview(){const {p}=S.aiPreview;showDialog('Review exactly what will leave this computer',`<div class="notice warn"><strong>${esc(p.provider)} · ${esc(p.model)}</strong><p>${esc(p.warning)}</p>Cost: unknown. API charges may apply.<p>Output limit: ${esc(p.limit)} · Effort: ${esc(p.effort||'provider default')}</p></div><label for="redacted-context">Actual selected fields — redact or exclude records before sending</label><textarea id="redacted-context" rows="12" spellcheck="false">${esc(JSON.stringify(p.context,null,2))}</textarea><p class="form-help">If edited, click “Update preview” before consent. The server binds consent to the exact preview.</p><details><summary>System instructions, task & output schema</summary><pre>${esc(p.system)}\n${esc(p.outbound_text)}</pre></details><h3>Attachments to transmit in full</h3><pre>${pretty(p.attachments)}</pre><div class="actions">${button('Update preview / redactions','redact-ai')}${button('I consent — send this preview','run-ai',p.token,'primary')}${button('Cancel','close')}</div>`);$('#redacted-context').oninput=()=>{$('[data-action=run-ai]').disabled=true;};}
async function inspectRecord(id){const r=await api('record?id='+id);let linked=[];for(const cid of [...(r.data.citation_ids||[]),...(r.data.contradicting_ids||[])]){try{linked.push(await api('record?id='+cid));}catch{}}if(r.data.source_id){try{linked.push(await api('record?id='+r.data.source_id));}catch{}}showDialog(r.data.title||r.data.name||r.kind,`${r.kind==='ai_artifact'?'<div class="notice warn">AI output is unreviewed research assistance. Inspect each source excerpt; a valid citation ID does not establish support.</div>':''}<pre>${pretty(r.data)}</pre>${linked.map(c=>`<section class="record"><h3>${esc(c.kind)} · ${esc(c.data.locator||c.data.title)}</h3><p>${esc(c.data.excerpt||'No excerpt. Inspect the source at its locator.')}</p><pre>${pretty(c.data)}</pre></section>`).join('')}<div class="actions">${(r.data.attachment_ids||[]).map(a=>`<a class="button small" href="/api/attachment?id=${esc(a)}">Download attachment ↓</a>`).join('')}${button('Edit / assess','edit',r.id)}${button('Raw provenance','provenance',r.id)}</div>`);}
async function action(a,id,el){
if(a.startsWith('smart-')){await smartAction(a,id,el);return;}
if(a==='close'){modal.close();return;}if(a==='refresh'){await refresh();return;}if(a==='import'){location.hash='import';return;}
if(a==='project'){S.formTitle='Create a private project';form(field('name','Project name'),async f=>{S.project=(await api('project',{name:f.name})).id;S.person=null;S.question=null;S.page=0;toast('Project created');});return;}
if(a.startsWith('new-')&&a!=='new-resource'){await editRecord(a.slice(4),null,id||S.person);return;}
if(a==='edit'){await editRecord('',id);return;}if(a==='record'){await inspectRecord(id);return;}
if(a==='provenance'){const p=await api('provenance?id='+id);showDialog('Imported data ↔ original source fields',`<div class="two"><section><h3>Interpreted record</h3><pre>${pretty(p.normalized)}</pre></section><section><h3>Preserved raw GEDCOM records</h3><pre>${pretty(p.original_records)}</pre></section></div><p class="meta">Line numbers link interpreted fields to their raw record. Raw preservation does not mean every field was interpreted.</p>`);return;}
if(a==='history'){const h=await api('history?id='+id);showDialog('Edit history',`<pre>${pretty(h)}</pre>`);return;}
if(a==='search-people'){S.peopleQuery=$('#people-search').value;S.page=0;await people();return;}
if(a==='page-next'||a==='prev'){S.page+=a==='prev'?-1:1;await route();return;}
if(a==='evidence-kind'){S.kind=id;S.page=0;await evidence();return;}
if(a==='recommend'){S.person=id;S.question=null;location.hash='next';return;}
if(a==='question'){const q=await api('record?id='+id);S.person=q.person;S.question=id;location.hash='next';if(S.route==='next')await next();return;}
if(a==='update-next'){S.person=$('#next-person').value;S.question=$('#next-question').value;await next();return;}
if(a==='resource'){const e=S.directory.find(e=>e.id===id);showDialog(e.name,`<p>${esc(e.description)}</p><dl class="details">${Object.entries(e).filter(([k])=>!['id','name','description'].includes(k)).map(([k,v])=>`<dt>${esc(k.replaceAll('_',' '))}</dt><dd>${esc(typeof v==='object'?JSON.stringify(v):v)}</dd>`).join('')}</dl><div class="actions">${external(e.url)}${button('Edit / verify / archive','edit-resource',id)}${button('Save resource','bookmark',id)}</div>`);return;}
if(a==='new-resource'||a==='edit-resource'){await editResource(id||null);return;}
if(a==='bookmark'){const e=S.directory.find(e=>e.id===id);await api('save',{project:S.project,kind:'bookmark',data:{title:e.name,url:e.url,resource_id:id,review:'unreviewed'}});toast('Resource saved in Evidence → bookmarks');return;}
if(a==='copy-query'){const r=S.recommendations.find(r=>r.resource.id===id);await navigator.clipboard.writeText(r.query);toast('Suggested query copied');return;}
if(a==='log-resource'){const r=S.recommendations.find(r=>r.resource.id===id);await editRecord('log',null,S.person,{collection_id:id,query:r.query,coverage:r.hypothesis.date.original||'',question_id:S.question||'',limitations:r.resource.limitations});return;}
if(a==='compare'){const list=await records('person',{offset:0,limit:1000});showDialog('Compare candidates without merging',`<label for="compare-person">Second candidate</label><select id="compare-person">${selectOptions(list.items.filter(p=>p.id!==id).map(p=>[p.id,p.data.name]),'','Choose a person')}</select>${button('Compare side by side','do-compare',id)}<div id="comparison"></div>`);return;}
if(a==='do-compare'){const second=$('#compare-person').value;if(!second)throw Error('Choose another person.');const candidates=await Promise.all([id,second].map(async pid=>({person:await api('record?id='+pid),assertions:await records('assertion',{person:pid,offset:0,limit:1000})})));$('#comparison').innerHTML=`<div class="two">${candidates.map(c=>`<section><h3>${esc(c.person.data.name)}</h3>${c.assertions.items.map(assertionCard).join('')}</section>`).join('')}</div>`;return;}
if(a==='preview-import'){await previewImport();return;}
if(a==='discard-import'){await api('import/discard',{stage:id});modal.close();toast('Preview discarded; no project created');return;}
if(a==='commit-import'){const b={stage:id,name:$('#import-name').value,identity_confirmed:$('#identity-confirmed')?.checked||false};el.disabled=true;try{const j=await api('import/commit',b);await pollJob(j.job,async r=>{S.project=r.project;S.person=null;S.question=null;modal.close();await refresh();toast(r.identical?'Identical snapshot recognized; no duplicates':'Import committed. Inspect the report and representative profiles.');});}catch(e){el.disabled=false;throw e;}return;}
if(a==='cancel-job'){await api('job/cancel',{id});toast('Cancellation requested');return;}
if(a==='import-report'){const all=await api('imports?project='+S.project);showDialog('Import report',`<pre>${pretty(all.find(i=>i.id===id)?.report)}</pre><p class="meta">Review representative people and their raw provenance before marking the migration complete.</p>`);return;}
if(a==='undo-import'){showDialog('Undo this imported snapshot?',`<p>The app will refuse undo if later edits exist. For a new untouched import, its separate project will be removed.</p><div class="actions">${button('Keep import','close')}${button('Undo untouched import','confirm-undo',id,'danger')}</div>`);return;}
if(a==='confirm-undo'){await api('import/undo',{id});modal.close();await refresh();toast('Import undone');return;}
if(a==='preview-restore'){const f=$('#restore-file').files[0];if(!f)throw Error('Choose a blueGene backup.');const data=await fileData(f);const j=await api('backup/preview',{data:data.data});await pollJob(j.job,async r=>{showDialog('Validated restore preview',`<p>${esc(r.note)}</p><pre>${pretty(r.counts)}</pre><p>${esc(r.projects.join(' · '))}</p>${button('Restore to separate database','restore',r.preview,'primary')}`);});return;}
if(a==='restore'){const j=await api('backup/restore',{preview:id});await pollJob(j.job,async r=>{showDialog('Restored into a separate destination',`<p>All links and attachments were restored. Your current notebook remains open.</p><p class="wrap">${esc(r.path)}</p><label>Launch the restored notebook on a separate port</label><pre>${esc(r.launch)}</pre>`);});return;}
if(a==='save-key'){await api('ai/configure',{provider:id,key:$('#key-'+id).value});$('#key-'+id).value='';await settings();toast('Credential stored on backend');return;}
if(a==='remove-key'){await api('ai/configure',{provider:id,key:''});await settings();return;}
if(a==='models'){const j=await api('ai/models',{provider:id});await pollJob(j.job,async r=>{modal.close();await settings();toast(r.models.length+' model IDs cached');});return;}
if(a==='test-model'){S.formTitle='User-triggered model test';form(field('model','Exact model ID',S.aiStatus.preferences.model||'')+field('inference','Test type','metadata','text',[['metadata','Metadata only (no inference)'],['inference','Minimal inference call — may incur charges']]),async f=>{const j=await api('ai/test',{provider:id,model:f.model,inference:f.inference==='inference'});const r=await pollJob(j.job);toast(r.note);},'Run selected test');return;}
if(a==='ai-workspace'){await aiWorkspace();return;}
if(a==='redact-ai'){const context=JSON.parse($('#redacted-context').value);const b={...S.aiPreview.b,context};const p=await api('ai/preview',b);S.aiPreview={b,p};showAIPreview();return;}
if(a==='run-ai'){el.disabled=true;const j=await api('ai/run',{token:id,consent:true});await pollJob(j.job,async r=>{await inspectRecord(r.id);toast('AI artifact saved for review; no claims changed');});return;}
throw Error('Action is not available: '+a);
}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el)return;if(el.tagName==='BUTTON')ev.preventDefault();try{await action(el.dataset.action,el.dataset.id,el);}catch(e){fail(e);}});
$('#project').onchange=async e=>{S.project=e.target.value;S.person=null;S.question=null;S.page=0;if(S.route==='person')location.hash='people';else await route();};
window.addEventListener('hashchange',()=>{S.page=0;modal.close();route().catch(fail);});
document.addEventListener('DOMContentLoaded',()=>bootstrap().then(route).catch(fail));
